/* Interface e persistência local do Meu Financeiro. */
(function () {
  'use strict';
  const F = window.FinanceCore;
  const STORAGE_KEY = 'meu-financeiro-state-v1';
  const $ = (selector, parent=document) => parent.querySelector(selector);
  const $$ = (selector, parent=document) => Array.from(parent.querySelectorAll(selector));
  const html = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const brl = cents => F.formatBRL(cents || 0);
  const fmtDate = iso => iso && /^\d{4}-\d{2}-\d{2}$/.test(iso) ? iso.split('-').reverse().join('/') : '—';
  const moneyInput = cents => (Number(cents || 0)/100).toFixed(2);
  const monthLabel = month => { const [y,m]=month.split('-').map(Number); return new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(new Date(y,m-1,1)); };
  const id = () => F.id();
  let state, currentMonth = F.monthISO(), activeView = 'dashboard', toastTimer, storageAvailable = true, storageLoadError = false;
  const content = $('#content'), dialog = $('#dialog'), dialogBody = $('#dialogBody');

  function loadState() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return F.demoState();
      const parsed = JSON.parse(raw); F.validateState(parsed); return parsed;
    } catch (error) {
      storageAvailable = false;
      storageLoadError = true;
      console.error('Não foi possível carregar os dados locais:', error);
      return F.initialState();
    }
  }
  function persist(showErrors=true) {
    if (storageLoadError) { storageAvailable = false; if(showErrors) showToast('Os dados anteriores parecem inválidos e foram preservados. Importe um backup válido ou use “Apagar tudo” para reiniciar conscientemente.'); return false; }
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); storageAvailable = true; return true; }
    catch (error) { storageAvailable = false; console.error('Falha ao salvar dados locais:', error); if(showErrors) showToast('Não foi possível salvar neste navegador. Exporte um backup e confira o espaço disponível.'); return false; }
  }
  function showToast(message) {
    const toast=$('#toast'); toast.textContent=message; toast.classList.add('show'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>toast.classList.remove('show'),3400);
  }
  function setView(view) { activeView=view; $$('.nav-link,.bottom-link').forEach(b=>b.classList.toggle('active',b.dataset.view===view)); render(); window.scrollTo({top:0,behavior:'smooth'}); }
  function prepareMonth(month) { const count=F.ensureRecurringOccurrences(state,month); if(count) persist(false); }
  function pageHeading(title, subtitle, action='') { return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${action}</div></div>`; }
  function emptyState(title, desc, button='') { return `<div class="empty-state"><div class="empty-icon" aria-hidden="true">⌁</div><strong>${html(title)}</strong><p>${html(desc)}</p>${button}</div>`; }
  function statCard(label,value,icon,foot,klass='') { return `<article class="stat-card ${klass}"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon" aria-hidden="true">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></article>`; }
  function button(label, action, klass='btn', extra='') { return `<button type="button" class="${klass}" data-action="${action}" ${extra}>${label}</button>`; }
  function categoryOptions(selected='', includeAll=false, categories=state.settings.categories) {
    const cats = Array.from(new Set(categories || F.DEFAULT_CATEGORIES));
    return `${includeAll?'<option value="">Todas as categorias</option>':''}` + cats.map(c=>`<option value="${html(c)}" ${c===selected?'selected':''}>${html(c)}</option>`).join('');
  }
  function allTransactionsForMonth() { return F.monthTransactions(state,currentMonth); }
  function paidExpenseCategory(category) { return F.categorySpent(state,currentMonth,category); }
  function categoryBudgetRows(limit=5) {
    const calc=F.calculateMonth(state,currentMonth); const rows=calc.budgets.slice().sort((a,b)=>b.spentCents-a.spentCents).slice(0,limit);
    if (!rows.length) return emptyState('Defina seus limites por categoria','Um limite ajuda a acompanhar seu gasto sem bloquear lançamentos.',button('Configurar orçamento','go-budget','btn btn-soft btn-small'));
    return `<div class="budget-progress-list">${rows.map(b=>{const pct=b.limitCents>0?Math.min(100,b.percent):0;const status=b.limitCents>0&&b.percent>=100?'danger':b.limitCents>0&&b.percent>=state.settings.alert90?'warn':'';return `<div class="budget-progress-row"><div class="budget-row-head"><strong>${html(b.category)}</strong><span>${brl(b.spentCents)} de ${brl(b.limitCents)}</span></div><div class="progress-track" role="progressbar" aria-label="Orçamento de ${html(b.category)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,Math.round(b.percent||0))}"><div class="progress-fill ${status}" style="width:${pct}%"></div></div><div class="legend-line"><span>${b.limitCents?`${Math.round(b.percent)}% utilizado`:'Sem limite definido'}</span><span>${brl(Math.max(0,b.remainingCents))} restantes</span></div></div>`;}).join('')}</div>`;
  }
  function billStatus(bill) { if(bill.status==='paid') return '<span class="badge badge-success">Paga</span>'; if(bill.dueDate < F.todayISO()) return '<span class="badge badge-danger">Atrasada</span>'; return '<span class="badge badge-neutral">Pendente</span>'; }
  function getBillList(month=currentMonth) { return F.monthBills(state,month).slice().sort((a,b)=>a.dueDate.localeCompare(b.dueDate)); }
  function dashboard() {
    const c=F.calculateMonth(state,currentMonth), bills=getBillList(), tx=allTransactionsForMonth();
    const [cy,cm]=currentMonth.split('-').map(Number); const previousMonth=F.monthISO(new Date(cy,cm-2,1)); const previousCalc=F.calculateMonth(state,previousMonth); const hasPrevious=F.monthTransactions(state,previousMonth).length>0||F.monthBills(state,previousMonth).length>0;
    const expenseDelta=c.paidExpensesCents-previousCalc.paidExpensesCents, incomeDelta=c.receivedIncomeCents-previousCalc.receivedIncomeCents;
    const totalSaved=state.goals.filter(g=>g.status!=='paused').reduce((sum,g)=>sum+F.getGoalBalance(state,g),0);
    const alerts=F.insights(state,currentMonth).slice(0,4);
    const actualBank=state.settings.currentBankBalanceCents==null?'<span class="muted">Não informado</span>':brl(state.settings.currentBankBalanceCents);
    const upcoming=bills.filter(b=>b.status!=='paid').slice(0,4);
    const recent=tx.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);
    return pageHeading('Visão geral',`Seu resumo para ${monthLabel(currentMonth)}. Pequenos registros frequentes tornam o planejamento mais útil.`,button('＋ Lançar movimentação','add-transaction','btn btn-primary'))+
      (state.demoMode?`<div class="note warning"><strong>Modo de exemplo ativo.</strong> Os valores exibidos são fictícios e servem apenas para demonstrar os cálculos. Use “Limpar dados de exemplo” nas configurações antes de começar seu controle real.</div>`:'')+
      (!storageAvailable?(storageLoadError?'<div class="note danger"><strong>Atenção:</strong> os dados salvos anteriormente parecem inválidos. Eles foram preservados; importe um backup válido ou use “Apagar tudo” para reiniciar conscientemente.</div>':'<div class="note danger"><strong>Atenção:</strong> o navegador não permitiu acessar ou salvar os dados locais. Exporte um backup assim que possível e verifique as permissões/armazenamento.</div>'):'')+
      `<section class="stat-grid" aria-label="Indicadores do mês">${statCard('Renda projetada',brl(c.projectedIncomeCents),'↗','Salário previsto + outras entradas')}${statCard('Despesas pagas',brl(c.paidExpensesCents),'↘','Despesas de consumo já pagas')}${statCard('Contas pendentes',brl(c.pendingBillsCents),'▤',`${c.pendingBillsCount} conta(s) ainda sem baixa`)}${statCard('Livre estimado',brl(c.projectedFreeCents),'◉','Após compromissos e aportes',c.projectedFreeCents<0?'negative':'')}${statCard('Em objetivos',brl(totalSaved),'◎','Acumulado nos objetivos ativos')}${statCard('Reserva de emergência',brl(c.emergencyBalanceCents),'⌂',c.emergencyTargetCents?`${Math.round(Math.min(100,c.emergencyBalanceCents/c.emergencyTargetCents*100))}% da meta estimada`:'Defina uma meta para acompanhar')}${statCard('Fluxo efetivo',brl(c.actualFlowCents),'⇄','Receitas recebidas menos saídas realizadas',c.actualFlowCents<0?'negative':'')}${statCard('Saldo bancário informado',actualBank,'▣','Valor manual, não calculado pelo sistema')}</section>
      <div class="content-grid"><div><section class="panel"><div class="panel-head"><div><h2>Orçamento por categoria</h2><p>Consumo já pago em relação aos limites definidos.</p></div>${button('Ver tudo','go-budget','text-action')}</div>${categoryBudgetRows(5)}</section>
      <section class="panel"><div class="panel-head"><div><h2>Movimentações recentes</h2><p>Receitas, gastos e alocações registrados neste mês.</p></div>${button('Ver histórico','go-transactions','text-action')}</div>${recent.length?`<div class="stack-list">${recent.map(transactionRow).join('')}</div>`:emptyState('Nenhum lançamento neste mês','Comece registrando uma despesa ou receita.',button('Adicionar lançamento','add-transaction','btn btn-soft btn-small'))}</section></div>
      <div><section class="panel"><div class="panel-head"><div><h2>Alertas e observações</h2><p>Baseados apenas nas informações cadastradas.</p></div></div><div class="alert-list">${alerts.map(a=>`<div class="alert-item ${a.level==='red'?'alert-red':a.level==='green'?'alert-green':''}"><span class="alert-mark">${a.level==='red'?'!':a.level==='green'?'✓':'•'}</span><span>${html(a.text)}</span></div>`).join('')}</div></section>
      <section class="panel"><div class="panel-head"><div><h2>Próximos vencimentos</h2><p>Contas ainda não marcadas como pagas.</p></div>${button('Ver contas','go-bills','text-action')}</div>${upcoming.length?`<div class="stack-list">${upcoming.map(b=>`<div class="list-row"><span class="row-icon">▤</span><div class="row-main"><strong>${html(b.name)}</strong><small>Vence ${fmtDate(b.dueDate)} · ${html(b.category)}</small></div><div class="row-end"><span class="row-amount">${brl(b.amountCents)}</span>${billStatus(b)}</div></div>`).join('')}</div>`:emptyState('Tudo em dia por aqui','Não há contas pendentes neste mês.')}</section>
      <section class="panel"><div class="panel-head"><div><h2>Comparação com o mês anterior</h2><p>${monthLabel(previousMonth)} versus ${monthLabel(currentMonth)}.</p></div></div>${hasPrevious?`<div class="mini-summary"><div><small>Variação de despesas pagas</small><strong class="${expenseDelta>0?'amount-negative':expenseDelta<0?'amount-positive':''}">${expenseDelta>0?'+':''}${brl(expenseDelta)}</strong><small>${expenseDelta>0?'Você registrou mais despesas':expenseDelta<0?'Você registrou menos despesas':'Sem variação'}.</small></div><div><small>Variação de renda recebida</small><strong class="${incomeDelta>=0?'amount-positive':'amount-negative'}">${incomeDelta>0?'+':''}${brl(incomeDelta)}</strong><small>${incomeDelta>0?'Maior entrada registrada':incomeDelta<0?'Menor entrada registrada':'Sem variação'}.</small></div></div>`:emptyState('Dados insuficientes para comparar','Registre movimentações ou contas no mês anterior para habilitar esta comparação.')}</section>
      <section class="panel"><div class="panel-head"><div><h2>Planejamento do mês</h2><p>Compromissos não são somados duas vezes.</p></div></div><div class="mini-summary"><div><small>Comprometido total</small><strong>${brl(c.committedCents)}</strong></div><div><small>Aportes líquidos</small><strong>${brl(c.allocatedNetCents)}</strong></div><div><small>Renda recebida</small><strong>${brl(c.receivedIncomeCents)}</strong></div><div><small>Despesas planejadas</small><strong>${brl(c.plannedExpensesCents)}</strong></div></div><p class="tiny muted">“Livre estimado” usa renda projetada, despesas pagas, despesas planejadas, contas pendentes e aportes. Não é o saldo bancário real.</p></section></div></div>`;
  }
  function transactionTypeLabel(type) { return ({income:'Receita',expense:'Despesa',goal_contribution:'Aporte em objetivo',goal_withdrawal:'Retirada de objetivo',emergency_contribution:'Aporte na reserva',emergency_withdrawal:'Retirada da reserva'})[type]||type; }
  function transactionIcon(t) { if(t.type==='income')return '↗'; if(t.type==='expense')return '↘'; if(t.type.includes('goal'))return '◎'; return '⌂'; }
  function transactionRow(t) {
    const incoming=t.type==='income'||t.type==='goal_withdrawal'||t.type==='emergency_withdrawal';
    const statusLabel=t.status==='planned'?'Planejado':t.status==='received'?'Recebido':t.status==='paid'?'Realizado':'Registrado';
    return `<div class="list-row"><span class="row-icon">${transactionIcon(t)}</span><div class="row-main"><strong>${html(t.description||transactionTypeLabel(t.type))}</strong><small>${fmtDate(t.date)} · ${html(t.category||transactionTypeLabel(t.type))} · ${transactionTypeLabel(t.type)}</small></div><div class="row-end"><span class="row-amount ${incoming?'amount-positive':'amount-negative'}">${incoming?'+':'−'}${brl(t.amountCents)}</span><span class="tag">${statusLabel}</span></div></div>`;
  }
  function transactionsView() {
    const tx=allTransactionsForMonth().slice().sort((a,b)=>b.date.localeCompare(a.date));
    return pageHeading('Movimentações','Registre entradas e saídas. Contas cadastradas devem ser baixadas em “Contas”, sem lançar o mesmo pagamento de novo aqui.',button('＋ Adicionar','add-transaction','btn btn-primary'))+
      `<form id="transactionFilter" class="toolbar"><input class="filter-control" name="q" placeholder="Buscar descrição…" aria-label="Buscar descrição" style="flex:2 1 180px"><select class="filter-control" name="type" aria-label="Filtrar tipo" style="flex:1 1 130px"><option value="">Todos os tipos</option><option value="income">Receitas</option><option value="expense">Despesas</option><option value="goal_contribution">Aportes em objetivos</option><option value="goal_withdrawal">Retiradas de objetivos</option><option value="emergency_contribution">Aportes na reserva</option><option value="emergency_withdrawal">Retiradas da reserva</option></select><select class="filter-control" name="category" aria-label="Filtrar categoria" style="flex:1 1 150px">${categoryOptions('',true)}</select><button class="btn btn-soft" type="submit">Filtrar</button><button class="btn" type="button" data-action="clear-tx-filter">Limpar</button></form>
      <div id="transactionResults">${transactionListMarkup(tx)}</div>`;
  }
  function transactionListMarkup(tx) {
    if(!tx.length) return emptyState('Nenhuma movimentação encontrada','Tente alterar os filtros ou registre seu primeiro lançamento.',button('Adicionar lançamento','add-transaction','btn btn-soft btn-small'));
    return `<div class="records-list">${tx.map(t=>`<article class="list-card"><div class="list-card-top"><div style="min-width:0;flex:1"><h3>${html(t.description||transactionTypeLabel(t.type))}</h3><p>${fmtDate(t.date)} · ${html(t.category||'Sem categoria')} · ${transactionTypeLabel(t.type)}</p>${t.account?`<p>Meio: ${html(t.account)}</p>`:''}</div><div style="text-align:right;flex-shrink:0"><strong class="row-amount ${t.type==='income'||t.type.endsWith('withdrawal')?'amount-positive':'amount-negative'}">${t.type==='income'||t.type.endsWith('withdrawal')?'+':'−'}${brl(t.amountCents)}</strong><div class="tag-row" style="justify-content:flex-end"><span class="tag">${t.status==='planned'?'Planejado':t.status==='received'?'Recebido':'Realizado'}</span></div></div></div><div class="list-card-actions" style="justify-content:flex-start;margin-top:12px">${button('Editar','edit-transaction','btn btn-small',`data-id="${html(t.id)}"`)}${button('Excluir','delete-transaction','btn btn-danger btn-small',`data-id="${html(t.id)}"`)}</div></article>`).join('')}</div>`;
  }
  function billsView() {
    const bills=getBillList();
    const paid=bills.filter(b=>b.status==='paid').length;
    return pageHeading('Contas e vencimentos','Cadastre contas mensais uma vez. As ocorrências futuras são criadas sem duplicação.',button('＋ Nova conta recorrente','add-bill','btn btn-primary'))+
      `<div class="stat-grid">${statCard('Total previsto',brl(F.sumCents(bills)),'▤',`${bills.length} conta(s) neste mês`)}${statCard('Já pago',brl(F.sumCents(bills.filter(b=>b.status==='paid'),F.actualBillAmount)),'✓',`${paid} conta(s) confirmada(s)`)}${statCard('Pendente',brl(F.sumCents(bills.filter(b=>b.status!=='paid'))),'◷',`${bills.filter(b=>b.status!=='paid'&&b.dueDate<F.todayISO()).length} atrasada(s)`)}${statCard('Modelos recorrentes',String(state.billTemplates.filter(t=>t.active!==false).length),'↻','Criam uma ocorrência por mês')}</div>
      <div class="toolbar"><select id="billFilter" class="filter-control" aria-label="Filtrar contas" style="max-width:240px"><option value="all">Todas as contas</option><option value="pending">Pendentes</option><option value="paid">Pagas</option><option value="late">Atrasadas</option></select></div>
      <div id="billResults">${billListMarkup(bills)}</div>
      <section class="panel" style="margin-top:18px"><div class="panel-head"><div><h2>Modelos recorrentes</h2><p>Desativar um modelo impede novas ocorrências, sem apagar o histórico.</p></div></div>${state.billTemplates.length?`<div class="records-list">${state.billTemplates.map(t=>`<article class="list-card"><div class="list-card-top"><div><h3>${html(t.name)}</h3><p>${html(t.category)} · Todo dia ${t.dueDay} · ${brl(t.amountCents)} / mês</p></div><span class="badge ${t.active!==false?'badge-success':'badge-neutral'}">${t.active!==false?'Ativo':'Pausado'}</span></div><div class="list-card-actions" style="justify-content:flex-start;margin-top:10px">${button(t.active!==false?'Pausar modelo':'Retomar modelo','toggle-template','btn btn-small',`data-id="${html(t.id)}"`)}${button('Editar modelo','edit-template','btn btn-small',`data-id="${html(t.id)}"`)}${button('Excluir modelo','delete-template','btn btn-danger btn-small',`data-id="${html(t.id)}"`)}</div></article>`).join('')}</div>`:emptyState('Nenhum modelo recorrente','Adicione aluguel, energia, internet ou outra conta mensal.')}</section>`;
  }
  function billListMarkup(bills) {
    if(!bills.length) return emptyState('Sem contas cadastradas neste mês','Adicione um modelo recorrente para que o sistema crie suas ocorrências mensais.',button('Adicionar conta','add-bill','btn btn-soft btn-small'));
    return `<div class="records-list">${bills.map(b=>`<article class="list-card" data-bill-card="${html(b.id)}"><div class="list-card-top"><div style="min-width:0;flex:1"><h3>${html(b.name)}</h3><p>${html(b.category)} · Vencimento ${fmtDate(b.dueDate)}</p>${b.notes?`<p>${html(b.notes)}</p>`:''}</div><div class="row-end"><span class="row-amount">${brl(b.status==='paid'?F.actualBillAmount(b):b.amountCents)}</span>${billStatus(b)}</div></div><div class="list-card-actions" style="justify-content:flex-start;margin-top:12px">${b.status==='paid'?button('Desfazer baixa','toggle-bill-paid','btn btn-small',`data-id="${html(b.id)}"`):button('Marcar como paga','toggle-bill-paid','btn btn-primary btn-small',`data-id="${html(b.id)}"`)}${button('Editar ocorrência','edit-bill','btn btn-small',`data-id="${html(b.id)}"`)}${button('Excluir ocorrência','delete-bill','btn btn-danger btn-small',`data-id="${html(b.id)}"`)}</div></article>`).join('')}</div>`;
  }
  function budgetView() {
    const calc=F.calculateMonth(state,currentMonth); const rows=calc.budgets;
    return pageHeading('Orçamento','Defina limites por categoria. O sistema alerta quando você se aproxima, mas não bloqueia despesas.',button('＋ Definir limite','add-budget','btn btn-primary'))+
      `<section class="panel"><div class="panel-head"><div><h2>Resumo das categorias</h2><p>Realizado considera despesas e contas pagas; despesas planejadas aparecem separadamente.</p></div></div>${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Categoria</th><th class="num">Limite</th><th class="num">Gasto pago</th><th class="num">Planejado</th><th class="num">Restante</th><th>Uso</th><th></th></tr></thead><tbody>${rows.map(b=>`<tr><td>${html(b.category)}</td><td class="num">${brl(b.limitCents)}</td><td class="num">${brl(b.spentCents)}</td><td class="num">${brl(b.plannedCents)}</td><td class="num">${brl(b.remainingCents)}</td><td>${b.limitCents?Math.round(b.percent)+'%':'—'}</td><td>${button('Editar','edit-budget','btn btn-small',`data-category="${html(b.category)}"`)}</td></tr>`).join('')}</tbody></table></div>`:emptyState('Nenhum limite definido','Você escolhe quais categorias acompanhar e quanto pretende gastar.',button('Criar limite','add-budget','btn btn-soft btn-small'))}</section>
      <div class="note"><strong>Como é calculado:</strong> “Gasto pago” soma despesas realizadas e contas pagas da categoria. Contas pendentes e despesas planejadas não são tratadas como gastos já realizados. Um aporte para objetivo ou reserva não entra no orçamento de consumo.</div>`;
  }
  function goalView() {
    const active=state.goals.filter(g=>g.status!=='completed'); const done=state.goals.filter(g=>g.status==='completed');
    return pageHeading('Objetivos','Guarde para compras, cursos, viagens ou qualquer meta. Aportes movimentam seu dinheiro livre sem virar despesa de consumo.',button('＋ Novo objetivo','add-goal','btn btn-primary'))+
      `<div class="goal-grid">${active.map(goalCard).join('')}${done.map(goalCard).join('')}</div>${!state.goals.length?emptyState('Seu próximo objetivo começa aqui','Defina o valor e, se souber, uma data-alvo e um aporte mensal.',button('Criar objetivo','add-goal','btn btn-soft btn-small')):''}`;
  }
  function goalCard(g) {
    const balance=F.getGoalBalance(state,g), remain=Math.max(0,g.targetCents-balance), pct=g.targetCents>0?Math.min(100,balance/g.targetCents*100):100;
    const months=g.monthlyCents>0?Math.ceil(remain/g.monthlyCents):null;
    const byDate=g.deadline?Math.max(0,F.monthsBetween(currentMonth+'-01',g.deadline)):null;
    const needed=byDate&&remain>0?Math.ceil(remain/byDate):null;
    const viability=needed!=null&&g.monthlyCents>0?g.monthlyCents>=needed:needed===0;
    return `<article class="goal-card"><div class="goal-top"><div class="goal-emoji">${g.kind==='Viagem'?'✈':g.kind==='Estudo'?'▤':g.kind==='Reserva'?'⌂':'◎'}</div><div style="flex:1;min-width:0"><h3>${html(g.name)}</h3><div class="goal-sub">${html(g.priority==='high'?'Prioridade alta':g.priority==='low'?'Prioridade baixa':'Prioridade média')} · ${html(g.status==='paused'?'Pausado':g.status==='completed'?'Concluído':'Em andamento')}</div></div><div class="list-card-actions">${button('⋯','goal-menu','btn btn-small',`data-id="${html(g.id)}" aria-label="Ações de ${html(g.name)}"`)}</div></div><div class="goal-numbers"><div><span>Acumulado</span><br><strong>${brl(balance)}</strong></div><div style="text-align:right"><span>Meta</span><br><strong>${brl(g.targetCents)}</strong></div></div><div class="progress-track" role="progressbar" aria-label="Progresso de ${html(g.name)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(pct)}"><div class="progress-fill ${pct>=100?'':' ' }" style="width:${pct}%"></div></div><div class="goal-meta"><span>${Math.round(pct)}% concluído · faltam ${brl(remain)}</span><span>${g.deadline?'Prazo '+fmtDate(g.deadline):'Sem prazo definido'}</span></div><div class="goal-meta"><span>${g.monthlyCents?`Aporte planejado ${brl(g.monthlyCents)}/mês`:'Sem aporte mensal definido'}</span><span>${remain===0?'Meta atingida':months!=null?`~${months} mês(es)`: 'Prazo não estimável'}</span></div>${needed!=null&&remain>0?`<div class="note ${viability?'':'warning'}" style="margin:12px 0 0;padding:9px 10px">${viability?'No ritmo atual, o prazo parece viável.':`Para o prazo, seriam cerca de ${brl(needed)}/mês. O aporte atual pode não bastar.`}</div>`:''}<div class="list-card-actions" style="justify-content:flex-start;margin-top:14px">${button('＋ Aportar','goal-operation','btn btn-primary btn-small',`data-id="${html(g.id)}" data-kind="contribution" ${g.status==='paused'||g.status==='completed'?'disabled':''}`)}${button('Retirar','goal-operation','btn btn-small',`data-id="${html(g.id)}" data-kind="withdrawal"`)}${button('Editar','edit-goal','btn btn-small',`data-id="${html(g.id)}"`)}${button(g.status==='paused'?'Retomar':g.status==='completed'?'Reabrir':'Pausar','toggle-goal','btn btn-small',`data-id="${html(g.id)}"`)}</div></article>`;
  }
  function emergencyView() {
    const c=F.calculateMonth(state,currentMonth); const bal=c.emergencyBalanceCents,target=c.emergencyTargetCents,pct=target?Math.min(100,bal/target*100):0,months=state.settings.essentialMonths||6;
    const tx=state.transactions.filter(t=>t.type.startsWith('emergency_')).slice().sort((a,b)=>b.date.localeCompare(a.date));
    const covers=c.essentialMonthlyCents?bal/c.essentialMonthlyCents:null;
    return pageHeading('Reserva de emergência','Uma reserva separada para imprevistos. Meta e cobertura dependem dos seus dados e podem ser ajustadas.',button('＋ Registrar aporte','emergency-operation','btn btn-primary'))+
      `<div class="stat-grid">${statCard('Saldo reservado',brl(bal),'⌂','Saldo inicial + aportes − retiradas')}${statCard('Meta estimada',target?brl(target):'Não definida','◎',target?`Baseada em ${months} meses essenciais`:'Cadastre despesas essenciais ou uma meta manual')}${statCard('Progresso',target?Math.round(pct)+'%':'—','◴',target?'Do saldo atual até a meta':'Configure uma meta para medir')}${statCard('Cobertura estimada',covers==null?'Dados insuficientes':covers.toLocaleString('pt-BR',{maximumFractionDigits:1})+' meses','▤','Com base nas despesas essenciais registradas')}</div>
      <section class="panel"><div class="panel-head"><div><h2>Progresso da reserva</h2><p>Transferências para a reserva são alocações, não despesas de consumo.</p></div>${button('Configurar meta','go-settings','btn btn-small')}</div>${target?`<div class="progress-track" style="height:12px"><div class="progress-fill" style="width:${pct}%"></div></div><div class="legend-line"><span>${brl(bal)} acumulados</span><span>${brl(Math.max(0,target-bal))} para a meta</span></div><p class="tiny muted">${state.settings.manualEmergencyTargetCents!=null?'Meta manual definida por você.':'Meta estimada com base na média essencial disponível e no número de meses escolhido.'}</p>`:emptyState('Ainda não há uma meta calculável','Informe uma estimativa de despesas essenciais ou configure um valor-alvo manual.',button('Abrir configurações','go-settings','btn btn-soft btn-small'))}</section>
      <section class="panel"><div class="panel-head"><div><h2>Histórico da reserva</h2><p>Aportes e retiradas anteriores, sem dupla contagem.</p></div></div>${tx.length?`<div class="stack-list">${tx.map(transactionRow).join('')}</div>`:emptyState('Sem movimentações na reserva','Registre o aporte inicial ou a próxima contribuição.',button('Registrar aporte','emergency-operation','btn btn-soft btn-small'))}</section>`;
  }
  function insightsView() {
    const c=F.calculateMonth(state,currentMonth), alerts=F.insights(state,currentMonth); const months=[];
    const [year,mon]=currentMonth.split('-').map(Number);
    for(let i=5;i>=0;i--){const d=new Date(year,mon-1-i,1);const month=F.monthISO(d);const calc=F.calculateMonth(state,month);months.push({month,label:new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(d).replace('.',''),spent:calc.paidExpensesCents});}
    const max=Math.max(1,...months.map(m=>m.spent));
    const categories=Array.from(new Set([...state.transactions.filter(t=>t.type==='expense'&&t.status==='paid'&&F.monthOf(t.date)===currentMonth).map(t=>t.category),...getBillList().filter(b=>b.status==='paid').map(b=>b.category)])).map(category=>({category,spent:paidExpenseCategory(category)})).sort((a,b)=>b.spent-a.spent).slice(0,5);
    return pageHeading('Relatórios e insights','Leia tendências como observações, não como certezas. Meses sem dados não permitem conclusões.',button('Imprimir relatório','print-report','btn btn-primary'))+
      `<div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Despesas pagas — últimos seis meses</h2><p>Contas pagas e gastos de consumo realizados.</p></div></div><div class="chart-bars" role="img" aria-label="Gráfico de despesas dos últimos seis meses">${months.map(m=>`<div class="chart-bar-col"><span class="chart-bar-value">${m.spent?brl(m.spent):'—'}</span><div class="chart-bar ${m.month===currentMonth?'current':''}" style="height:${m.spent?Math.max(3,m.spent/max*78):3}px" title="${html(m.label)}: ${brl(m.spent)}"></div><span class="chart-bar-label">${html(m.label)}</span></div>`).join('')}</div><p class="tiny muted">${months.filter(m=>m.spent>0).length<2?'Dados insuficientes para comparar tendências entre meses.':'Compare os valores registrados. Diferenças podem refletir lançamentos incompletos.'}</p></section><section class="panel"><div class="panel-head"><div><h2>Maiores categorias do mês</h2><p>Ordenadas pelo total pago.</p></div></div>${categories.length?`<div class="stack-list">${categories.map((x,i)=>`<div class="list-row"><span class="row-icon">${i+1}</span><div class="row-main"><strong>${html(x.category)}</strong><small>Despesas pagas</small></div><div class="row-end"><span class="row-amount">${brl(x.spent)}</span></div></div>`).join('')}</div>`:emptyState('Sem despesas realizadas','Com mais registros, este relatório vai destacar suas principais categorias.')}</section></div>
      <section class="panel"><div class="panel-head"><div><h2>Observações deste mês</h2><p>Alertas gerados exclusivamente a partir dos dados registrados.</p></div></div><div class="alert-list">${alerts.map(a=>`<div class="alert-item ${a.level==='red'?'alert-red':a.level==='green'?'alert-green':''}"><span class="alert-mark">${a.level==='red'?'!':a.level==='green'?'✓':'•'}</span><span>${html(a.text)}</span></div>`).join('')}</div></section>
      <section class="panel"><div class="panel-head"><div><h2>Resumo numérico</h2><p>${monthLabel(currentMonth)}</p></div></div><div class="table-wrap"><table class="data-table"><tbody><tr><td>Renda projetada</td><td class="num">${brl(c.projectedIncomeCents)}</td></tr><tr><td>Renda efetivamente recebida</td><td class="num">${brl(c.receivedIncomeCents)}</td></tr><tr><td>Despesas pagas</td><td class="num">${brl(c.paidExpensesCents)}</td></tr><tr><td>Contas pendentes</td><td class="num">${brl(c.pendingBillsCents)}</td></tr><tr><td>Aportes líquidos (objetivos + reserva)</td><td class="num">${brl(c.allocatedNetCents)}</td></tr><tr><td><strong>Dinheiro livre projetado</strong></td><td class="num"><strong>${brl(c.projectedFreeCents)}</strong></td></tr></tbody></table></div></section>`;
  }
  function settingsView() {
    const s=state.settings;
    return pageHeading('Configurações e backup','Personalize renda, critérios e categorias. Os dados financeiros não são enviados a servidores.', '')+
      `<div class="settings-grid"><section class="panel"><div class="panel-head"><div><h2>Renda e preferências</h2><p>Use o salário líquido como referência do planejamento.</p></div></div><form id="settingsForm" class="form-grid"><div class="field full"><label for="salaryExpected">Salário líquido mensal previsto (R$)</label><input id="salaryExpected" name="salaryExpected" type="number" min="0" step="0.01" value="${moneyInput(s.salaryExpectedCents)}" required><span class="help">Valor esperado; se registrar uma receita com categoria “Salário” no mês, ela substitui a previsão para esse mês.</span></div><div class="field"><label for="salaryDay">Dia esperado de recebimento</label><input id="salaryDay" name="salaryDay" type="number" min="1" max="31" step="1" value="${s.salaryDay||5}"></div><div class="field"><label for="bankBalance">Saldo bancário real informado (R$)</label><input id="bankBalance" name="bankBalance" type="number" min="0" step="0.01" value="${s.currentBankBalanceCents==null?'':moneyInput(s.currentBankBalanceCents)}" placeholder="Não informado"><span class="help">É manual e independente do saldo projetado.</span></div><div class="field"><label for="essentialMonths">Meses de despesas essenciais na meta</label><input id="essentialMonths" name="essentialMonths" type="number" min="0" max="60" step="1" value="${s.essentialMonths??6}"></div><div class="field"><label for="emergencyInitial">Saldo inicial já reservado (R$)</label><input id="emergencyInitial" name="emergencyInitial" type="number" min="0" step="0.01" value="${moneyInput(state.emergencyInitialCents||0)}"><span class="help">Dinheiro que já existia na reserva antes de começar a registrar aportes.</span></div><div class="field"><label for="manualTarget">Meta manual da reserva (R$)</label><input id="manualTarget" name="manualTarget" type="number" min="0" step="0.01" value="${s.manualEmergencyTargetCents==null?'':moneyInput(s.manualEmergencyTargetCents)}" placeholder="Deixe vazio para estimar"><span class="help">Se preencher, substitui a meta calculada com despesas essenciais.</span></div><div class="field"><label for="alert70">Primeiro alerta de orçamento (%)</label><input id="alert70" name="alert70" type="number" min="1" max="100" step="1" value="${s.alert70||70}"></div><div class="field"><label for="alert90">Segundo alerta de orçamento (%)</label><input id="alert90" name="alert90" type="number" min="1" max="100" step="1" value="${s.alert90||90}"></div><div class="field full"><label for="categories">Categorias (separadas por vírgula)</label><textarea id="categories" name="categories" rows="3">${html((s.categories||F.DEFAULT_CATEGORIES).join(', '))}</textarea><span class="help">Ao remover uma categoria já usada, os lançamentos antigos continuam com o nome original.</span></div><div class="full form-actions"><button class="btn btn-primary" type="submit">Salvar configurações</button></div></form></section>
      <section><section class="panel"><div class="panel-head"><div><h2>Backup e exportação</h2><p>Guarde cópias regulares fora deste navegador.</p></div></div><div class="settings-actions">${button('Exportar backup JSON','export-json','btn btn-primary')}${button('Restaurar backup JSON','import-json','btn')}${button('Exportar movimentações CSV','export-csv','btn')}${button('Imprimir relatório do mês','print-report','btn')}</div><div class="note"><strong>Privacidade:</strong> o armazenamento é local por navegador/dispositivo. Não há sincronização automática, e limpar os dados do site pode apagar seu histórico. O backup JSON contém suas informações financeiras; guarde-o em local privado.</div></section>
      <section class="panel"><div class="panel-head"><div><h2>Dados de demonstração</h2><p>Remova os exemplos sem apagar registros pessoais.</p></div></div>${state.demoMode?`<div class="note warning">O modo de exemplo está ativo. Itens marcados como exemplo não são dados financeiros reais.</div>`:'<p class="tiny muted">Não há selo de modo de exemplo ativo. Ainda assim, confira seus lançamentos antes de usar relatórios.</p>'}${button('Limpar dados de exemplo','clear-demo','btn btn-soft')}
      <hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><h3 style="font-size:13px;margin:0 0 7px">Apagar todos os dados</h3><p class="tiny muted">Esta ação apaga configurações, lançamentos, contas, objetivos e histórico deste navegador. Faça backup primeiro.</p>${button('Apagar tudo…','wipe-all','btn btn-danger')}</section>
      <section class="panel"><div class="panel-head"><div><h2>Como interpretar os valores</h2><p>Regras principais de contabilização.</p></div></div><div class="stack-list"><div class="list-row"><span class="row-icon">↗</span><div class="row-main"><strong>Renda prevista x recebida</strong><small>A previsão ajuda no orçamento. Só lançamentos marcados como recebidos entram no total efetivamente recebido.</small></div></div><div class="list-row"><span class="row-icon">↘</span><div class="row-main"><strong>Despesa paga x planejada</strong><small>Despesas planejadas e contas pendentes afetam o saldo projetado, não o total já pago.</small></div></div><div class="list-row"><span class="row-icon">◎</span><div class="row-main"><strong>Aportes</strong><small>Diminuem o dinheiro livre e aumentam o saldo do objetivo/reserva. Não são consumo.</small></div></div><div class="list-row"><span class="row-icon">▣</span><div class="row-main"><strong>Saldo bancário real</strong><small>É uma informação manual, não é inferida a partir do histórico.</small></div></div></div></section></section></div>`;
  }
  function render() {
    prepareMonth(currentMonth);
    $('#monthPicker').value=currentMonth;
    $('#demoBadge').hidden=!state.demoMode;
    $$('.nav-link,.bottom-link').forEach(b=>b.classList.toggle('active',b.dataset.view===activeView));
    $('#floatingAdd').hidden=['settings'].includes(activeView);
    const views={dashboard,transactions:transactionsView,bills:billsView,budget:budgetView,goals:goalView,emergency:emergencyView,insights:insightsView,settings:settingsView};
    content.innerHTML=(views[activeView]||dashboard)();
    if(!storageAvailable) $('#demoBadge').hidden=true;
  }
  function openDialog(title,eyebrow,body) {
    $('#dialogTitle').textContent=title; $('#dialogEyebrow').textContent=eyebrow; dialogBody.innerHTML=body;
    if(typeof dialog.showModal==='function') dialog.showModal(); else dialog.setAttribute('open','');
  }
  function closeDialog() { if(typeof dialog.close==='function') dialog.close(); else dialog.removeAttribute('open'); }
  function transactionForm(existing=null, preselect={}) {
    const t=existing||{type:preselect.type||'expense',amountCents:0,date:F.todayISO(),category:preselect.category||'Alimentação',description:'',account:'',status:preselect.type==='income'?'received':preselect.type==='expense'?'paid':'paid',essential:false,goalId:preselect.goalId||''};
    const type=t.type;
    const statusOptions=type==='income'?[['received','Recebido'],['planned','Previsto']]:type==='expense'?[['paid','Pago/realizado'],['planned','Planejado']]:[['paid','Registrado']];
    const categories= type==='income'?Array.from(new Set([...(state.settings.categories||[]).filter(c=>c.toLowerCase().includes('salário')||c.toLowerCase().includes('salario')||c.toLowerCase().includes('renda')), 'Salário','Renda extra'])):type==='expense'?state.settings.categories.filter(c=>!['Salário','Renda extra'].includes(c)):['Objetivos','Reserva de emergência','Outros'];
    return `<form id="transactionForm" class="dialog-form" data-id="${existing?html(existing.id):''}"><div class="form-grid"><div class="field full"><label for="txType">Tipo</label><select name="type" id="txType">${[['expense','Despesa'],['income','Receita'],['goal_contribution','Aporte em objetivo'],['goal_withdrawal','Retirada de objetivo'],['emergency_contribution','Aporte na reserva'],['emergency_withdrawal','Retirada da reserva']].map(([v,l])=>`<option value="${v}" ${type===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="txAmount">Valor (R$)</label><input id="txAmount" name="amount" type="number" min="0.01" step="0.01" value="${moneyInput(t.amountCents)}" required></div><div class="field"><label for="txDate">Data</label><input id="txDate" name="date" type="date" value="${html(t.date)}" required></div><div class="field" id="txCategoryWrap"><label for="txCategory">Categoria</label><select id="txCategory" name="category">${categories.map(c=>`<option value="${html(c)}" ${c===t.category?'selected':''}>${html(c)}</option>`).join('')}</select></div><div class="field"><label for="txStatus">Situação</label><select id="txStatus" name="status">${statusOptions.map(([v,l])=>`<option value="${v}" ${t.status===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field full"><label for="txDescription">Descrição</label><input id="txDescription" name="description" maxlength="120" value="${html(t.description||'')}" placeholder="Ex.: mercado, salário, farmácia"></div><div class="field"><label for="txAccount">Conta/meio de pagamento (opcional)</label><input id="txAccount" name="account" maxlength="60" value="${html(t.account||'')}" placeholder="Pix, débito, dinheiro…"></div><div class="field" id="txGoalWrap" ${type.includes('goal')?'':'hidden'}><label for="txGoal">Objetivo</label><select id="txGoal" name="goalId">${state.goals.map(g=>`<option value="${html(g.id)}" ${(t.goalId||preselect.goalId)===g.id?'selected':''}>${html(g.name)}</option>`).join('')}</select></div><div class="full" id="txEssentialWrap" ${type==='expense'?'':'hidden'}><label class="inline-check"><input type="checkbox" name="essential" ${t.essential?'checked':''}> Considerar despesa essencial para a meta da reserva</label></div></div><div class="note">Aportes e retiradas são transferências entre dinheiro livre e valores reservados; não entram como despesa de consumo.</div><div class="form-actions"><button class="btn" type="button" data-action="close-dialog">Cancelar</button><button class="btn btn-primary" type="submit">${existing?'Salvar alterações':'Salvar lançamento'}</button></div></form>`;
  }
  function billForm(existing=null) {
    const b=existing||{name:'',category:'Moradia',amountCents:0,dueDay:10,essential:true,notes:'',active:true};
    return `<form id="billForm" class="dialog-form" data-id="${existing?html(existing.id):''}"><div class="form-grid"><div class="field full"><label for="billName">Nome da conta</label><input id="billName" name="name" maxlength="100" value="${html(b.name)}" required placeholder="Ex.: aluguel, energia, internet"></div><div class="field"><label for="billAmount">Valor previsto (R$)</label><input id="billAmount" name="amount" type="number" min="0.01" step="0.01" value="${moneyInput(b.amountCents)}" required></div><div class="field"><label for="billDue">Dia de vencimento</label><input id="billDue" name="dueDay" type="number" min="1" max="31" step="1" value="${b.dueDay||10}" required></div><div class="field"><label for="billCategory">Categoria</label><select id="billCategory" name="category">${categoryOptions(b.category,false,state.settings.categories.filter(c=>!['Salário','Renda extra'].includes(c)))}</select></div><div class="field"><label for="billRecurrence">Recorrência</label><select id="billRecurrence" name="recurrence"><option value="monthly">Todo mês</option></select></div><div class="field full"><label for="billNotes">Observações (opcional)</label><input id="billNotes" name="notes" maxlength="150" value="${html(b.notes||'')}" placeholder="Detalhes úteis"></div><div class="field full"><label class="inline-check"><input type="checkbox" name="essential" ${b.essential?'checked':''}> Conta essencial para o custo de vida</label></div><div class="field full"><label class="inline-check"><input type="checkbox" name="active" ${b.active!==false?'checked':''}> Criar ocorrências futuras automaticamente</label></div></div><div class="note">A conta será criada para ${monthLabel(currentMonth)}. Ao abrir outros meses, o sistema cria apenas a ocorrência que ainda não existe. Nunca marca uma conta como paga automaticamente.</div><div class="form-actions"><button class="btn" type="button" data-action="close-dialog">Cancelar</button><button class="btn btn-primary" type="submit">${existing?'Salvar modelo':'Criar conta recorrente'}</button></div></form>`;
  }
  function billOccurrenceForm(b) {
    return `<form id="billOccurrenceForm" class="dialog-form" data-id="${html(b.id)}"><div class="form-grid"><div class="field full"><label for="occName">Nome</label><input id="occName" name="name" maxlength="100" required value="${html(b.name)}"></div><div class="field"><label for="occAmount">Valor previsto (R$)</label><input id="occAmount" name="amount" type="number" min="0.01" step="0.01" required value="${moneyInput(b.amountCents)}"></div><div class="field"><label for="occDate">Vencimento</label><input id="occDate" name="dueDate" type="date" required value="${html(b.dueDate)}"></div><div class="field"><label for="occCategory">Categoria</label><select id="occCategory" name="category">${categoryOptions(b.category,false,state.settings.categories)}</select></div><div class="field"><label for="occStatus">Situação</label><select id="occStatus" name="status"><option value="pending" ${b.status==='pending'?'selected':''}>Pendente</option><option value="paid" ${b.status==='paid'?'selected':''}>Paga</option></select></div><div class="field"><label for="occPaidAmount">Valor efetivamente pago (R$)</label><input id="occPaidAmount" name="paidAmount" type="number" min="0" step="0.01" value="${b.paidAmountCents==null?'':moneyInput(b.paidAmountCents)}" placeholder="Igual ao previsto"></div><div class="field"><label for="occPaidDate">Data de pagamento</label><input id="occPaidDate" name="paidDate" type="date" value="${html(b.paidDate||'')}"></div><div class="field full"><label for="occNotes">Observações</label><input id="occNotes" name="notes" maxlength="150" value="${html(b.notes||'')}"></div><div class="field full"><label class="inline-check"><input type="checkbox" name="essential" ${b.essential?'checked':''}> Conta essencial</label></div></div><div class="note">Esta edição afeta somente esta ocorrência. O modelo recorrente permanece separado para os meses futuros.</div><div class="form-actions"><button class="btn" type="button" data-action="close-dialog">Cancelar</button><button class="btn btn-primary" type="submit">Salvar ocorrência</button></div></form>`;
  }
  function budgetForm(existing=null) {
    const b=existing||{category:state.settings.categories.find(c=>!['Salário','Renda extra'].includes(c))||'Outros',limitCents:0};
    const choices=Array.from(new Set([...state.settings.categories.filter(c=>!['Salário','Renda extra'].includes(c)),...state.budgets.map(x=>x.category)]));
    return `<form id="budgetForm" class="dialog-form" data-category="${existing?html(existing.category):''}"><div class="form-grid"><div class="field full"><label for="budgetCategory">Categoria</label><select id="budgetCategory" name="category">${choices.map(c=>`<option value="${html(c)}" ${b.category===c?'selected':''}>${html(c)}</option>`).join('')}</select></div><div class="field full"><label for="budgetLimit">Limite mensal (R$)</label><input id="budgetLimit" name="limit" type="number" min="0" step="0.01" value="${moneyInput(b.limitCents)}" required></div></div><div class="form-actions"><button class="btn" type="button" data-action="close-dialog">Cancelar</button><button class="btn btn-primary" type="submit">Salvar limite</button></div></form>`;
  }
  function goalForm(existing=null) {
    const g=existing||{name:'',targetCents:0,initialCents:0,deadline:'',monthlyCents:0,priority:'medium',status:'active',kind:'Compra'};
    return `<form id="goalForm" class="dialog-form" data-id="${existing?html(g.id):''}"><div class="form-grid"><div class="field full"><label for="goalName">Nome do objetivo</label><input id="goalName" name="name" maxlength="100" value="${html(g.name)}" required placeholder="Ex.: computador, viagem, curso"></div><div class="field"><label for="goalTarget">Valor desejado (R$)</label><input id="goalTarget" name="target" type="number" min="0.01" step="0.01" value="${moneyInput(g.targetCents)}" required></div><div class="field"><label for="goalInitial">Já acumulado antes do sistema (R$)</label><input id="goalInitial" name="initial" type="number" min="0" step="0.01" value="${moneyInput(g.initialCents||0)}" required></div><div class="field"><label for="goalMonthly">Aporte mensal planejado (R$)</label><input id="goalMonthly" name="monthly" type="number" min="0" step="0.01" value="${moneyInput(g.monthlyCents||0)}"></div><div class="field"><label for="goalDeadline">Data-alvo (opcional)</label><input id="goalDeadline" name="deadline" type="date" value="${html(g.deadline||'')}"></div><div class="field"><label for="goalPriority">Prioridade</label><select id="goalPriority" name="priority"><option value="high" ${g.priority==='high'?'selected':''}>Alta</option><option value="medium" ${g.priority==='medium'?'selected':''}>Média</option><option value="low" ${g.priority==='low'?'selected':''}>Baixa</option></select></div><div class="field"><label for="goalKind">Tipo</label><select id="goalKind" name="kind">${['Compra','Viagem','Estudo','Reserva','Outro'].map(x=>`<option ${g.kind===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label for="goalStatus">Situação</label><select id="goalStatus" name="status"><option value="active" ${g.status==='active'?'selected':''}>Em andamento</option><option value="paused" ${g.status==='paused'?'selected':''}>Pausado</option><option value="completed" ${g.status==='completed'?'selected':''}>Concluído</option></select></div></div><div class="note">O valor inicial é um saldo pré-existente. Use “Aportar” para registrar contribuições posteriores e manter histórico.</div><div class="form-actions"><button class="btn" type="button" data-action="close-dialog">Cancelar</button><button class="btn btn-primary" type="submit">Salvar objetivo</button></div></form>`;
  }
  function goalOperationForm(goalId, operation='contribution') {
    const g=state.goals.find(x=>x.id===goalId);
    return `<form id="goalOperationForm" class="dialog-form" data-goal-id="${html(goalId)}"><div class="form-grid"><div class="field full"><label for="goalOp">Operação</label><select name="operation" id="goalOp"><option value="contribution" ${operation==='contribution'?'selected':''}>Aporte ao objetivo</option><option value="withdrawal" ${operation==='withdrawal'?'selected':''}>Retirada do objetivo</option></select></div><div class="field full"><label for="goalOpAmount">Valor (R$)</label><input id="goalOpAmount" name="amount" type="number" min="0.01" step="0.01" required></div><div class="field full"><label for="goalOpDate">Data</label><input id="goalOpDate" name="date" type="date" value="${F.todayISO()}" required></div><div class="field full"><label for="goalOpDesc">Descrição (opcional)</label><input id="goalOpDesc" name="description" maxlength="100" value="${html(g?g.name:'')}" placeholder="Aporte/retirada"></div></div><div class="note">${g?`Saldo atual deste objetivo: ${brl(F.getGoalBalance(state,g))}.`:'Selecione um objetivo.'} O valor de uma retirada não pode superar o saldo acumulado.</div><div class="form-actions"><button class="btn" type="button" data-action="close-dialog">Cancelar</button><button class="btn btn-primary" type="submit">Registrar</button></div></form>`;
  }
  function emergencyOperationForm() {
    return `<form id="emergencyOperationForm" class="dialog-form"><div class="form-grid"><div class="field full"><label for="emergencyOp">Operação</label><select id="emergencyOp" name="operation"><option value="contribution">Aporte na reserva</option><option value="withdrawal">Retirada da reserva</option></select></div><div class="field full"><label for="emergencyAmount">Valor (R$)</label><input id="emergencyAmount" name="amount" type="number" min="0.01" step="0.01" required></div><div class="field full"><label for="emergencyDate">Data</label><input id="emergencyDate" name="date" type="date" value="${F.todayISO()}" required></div><div class="field full"><label for="emergencyDesc">Descrição (opcional)</label><input id="emergencyDesc" name="description" maxlength="100" placeholder="Aporte mensal, imprevisto…"></div></div><div class="note">Saldo atual da reserva: ${brl(F.getEmergencyBalance(state))}. Retiradas acima do saldo disponível serão recusadas.</div><div class="form-actions"><button class="btn" type="button" data-action="close-dialog">Cancelar</button><button class="btn btn-primary" type="submit">Registrar</button></div></form>`;
  }
  function openByAction(action, el) {
    const itemId=el?.dataset.id;
    switch(action) {
      case 'add-transaction': openDialog('Adicionar movimentação','NOVO LANÇAMENTO',transactionForm()); break;
      case 'edit-transaction': {const t=state.transactions.find(x=>x.id===itemId);if(t)openDialog('Editar movimentação','EDITAR LANÇAMENTO',transactionForm(t));break;}
      case 'add-bill': openDialog('Nova conta recorrente','CONTAS FIXAS',billForm());break;
      case 'edit-bill': {const b=state.bills.find(x=>x.id===itemId);if(b)openDialog('Editar ocorrência','CONTA DO MÊS',billOccurrenceForm(b));break;}
      case 'add-budget': openDialog('Definir limite mensal','ORÇAMENTO',budgetForm());break;
      case 'edit-budget': {const b=state.budgets.find(x=>x.category===el.dataset.category);if(b)openDialog('Editar limite','ORÇAMENTO',budgetForm(b));break;}
      case 'add-goal': openDialog('Novo objetivo','OBJETIVOS',goalForm());break;
      case 'edit-goal': {const g=state.goals.find(x=>x.id===itemId);if(g)openDialog('Editar objetivo','OBJETIVOS',goalForm(g));break;}
      case 'goal-operation': openDialog(el.dataset.kind==='withdrawal'?'Retirar de um objetivo':'Aportar em objetivo','OBJETIVOS',goalOperationForm(itemId,el.dataset.kind||'contribution'));break;
      case 'emergency-operation': openDialog('Movimentar reserva','RESERVA DE EMERGÊNCIA',emergencyOperationForm());break;
      case 'go-budget': setView('budget');break;case 'go-transactions':setView('transactions');break;case 'go-bills':setView('bills');break;case 'go-settings':setView('settings');break;
      case 'export-json': exportJSON();break;case 'import-json': $('#backupPicker').click();break;case 'export-csv': exportCSV();break;case 'print-report': window.print();break;
      case 'clear-demo': clearDemo();break;case 'wipe-all': wipeAll();break;
      case 'close-dialog': closeDialog();break;
      case 'toggle-bill-paid': toggleBillPaid(itemId);break;case 'delete-bill': deleteBill(itemId);break;
      case 'toggle-template': toggleTemplate(itemId);break;case 'edit-template': {const t=state.billTemplates.find(x=>x.id===itemId);if(t)openDialog('Editar modelo recorrente','CONTAS FIXAS',billForm(t));break;}case 'delete-template':deleteTemplate(itemId);break;
      case 'delete-transaction': deleteTransaction(itemId);break;case 'toggle-goal':toggleGoal(itemId);break;case 'goal-menu': {const g=state.goals.find(x=>x.id===itemId);if(g)openDialog('Ações do objetivo','OBJETIVOS',`<div class="dialog-form"><p><strong>${html(g.name)}</strong></p><div class="settings-actions">${button('Aportar','goal-operation','btn btn-primary',`data-id="${html(g.id)}" data-kind="contribution"`)}${button('Retirar','goal-operation','btn',`data-id="${html(g.id)}" data-kind="withdrawal"`)}${button('Editar','edit-goal','btn',`data-id="${html(g.id)}"`)}${button('Excluir objetivo','delete-goal','btn btn-danger',`data-id="${html(g.id)}"`)}</div><div class="form-actions"><button class="btn" type="button" data-action="close-dialog">Fechar</button></div></div>`);break;}
      case 'delete-goal':deleteGoal(itemId);break;
    }
  }
  function getFormData(form) { return Object.fromEntries(new FormData(form).entries()); }
  function amount(formData,key='amount') { const cents=F.centsFromInput(formData[key]); if(!Number.isSafeInteger(cents)||cents<0) throw new Error('Informe um valor válido, sem negativos.'); return cents; }
  function submitTransaction(form) {
    const d=getFormData(form); if(!F.validDate(d.date)) throw new Error('Informe uma data válida.'); const cents=amount(d); if(cents<=0)throw new Error('O valor deve ser maior que zero.');
    const type=d.type; const oldId=form.dataset.id; const old=oldId?state.transactions.find(t=>t.id===oldId):null;
    if(type.includes('goal')) {if(!state.goals.some(g=>g.id===d.goalId))throw new Error('Escolha um objetivo válido.');if(type==='goal_withdrawal'&&cents>F.getGoalBalance(state,state.goals.find(g=>g.id===d.goalId)))throw new Error('A retirada supera o saldo acumulado deste objetivo.');}
    if(type==='emergency_withdrawal'&&cents>F.getEmergencyBalance(state))throw new Error('A retirada supera o saldo atual da reserva.');
    let status=d.status||'paid'; if(type!=='income'&&type!=='expense') status='paid';
    const tx={...(old||{}),id:oldId||id(),demo:false,type,amountCents:cents,date:d.date,category:d.category|| (type.includes('goal')?'Objetivos':type.includes('emergency')?'Reserva de emergência':'Outros'),description:(d.description||'').trim(),account:(d.account||'').trim(),status,essential:d.essential==='on',goalId:type.includes('goal')?d.goalId:undefined};
    if(old) state.transactions=state.transactions.map(t=>t.id===oldId?tx:t); else state.transactions.push(tx);
    persist(); closeDialog();render();showToast(old?'Movimentação atualizada.':'Movimentação registrada.');
  }
  function submitBillTemplate(form) {
    const d=getFormData(form);const amountC=amount(d);if(amountC<=0)throw new Error('O valor previsto deve ser maior que zero.');const due=Number(d.dueDay);if(!Number.isInteger(due)||due<1||due>31)throw new Error('O dia deve estar entre 1 e 31.');const editId=form.dataset.id;const old=editId?state.billTemplates.find(t=>t.id===editId):null;
    const t={...(old||{}),id:editId||id(),demo:false,name:d.name.trim(),category:d.category,amountCents:amountC,dueDay:due,recurrence:'monthly',active:d.active==='on',essential:d.essential==='on',notes:(d.notes||'').trim()};
    if(!t.name)throw new Error('Informe um nome para a conta.');
    if(old){state.billTemplates=state.billTemplates.map(x=>x.id===editId?t:x);}else state.billTemplates.push(t);
    // Corrige a ocorrência do mês selecionado se já existir para esse modelo.
    const occ=state.bills.find(b=>b.templateId===t.id&&b.occurrenceKey===`${t.id}:${currentMonth}`);
    if(occ&&occ.status!=='paid'){occ.demo=false;occ.name=t.name;occ.category=t.category;occ.amountCents=t.amountCents;occ.dueDate=F.dateForDueDay(currentMonth,t.dueDay);occ.essential=t.essential;occ.notes=t.notes;}
    F.ensureRecurringOccurrences(state,currentMonth);persist();closeDialog();render();showToast(old?'Modelo atualizado.':'Conta recorrente criada.');
  }
  function submitBillOccurrence(form) {
    const d=getFormData(form),b=state.bills.find(x=>x.id===form.dataset.id);if(!b)throw new Error('Conta não encontrada.');const cents=amount(d);if(cents<=0)throw new Error('Valor inválido.');if(!F.validDate(d.dueDate))throw new Error('Data de vencimento inválida.');
    if(d.status==='paid'){const paid=String(d.paidAmount||'').trim()===''?cents:F.centsFromInput(d.paidAmount);if(!Number.isSafeInteger(paid)||paid<0)throw new Error('Valor efetivamente pago inválido.');b.paidAmountCents=paid;b.paidDate=F.validDate(d.paidDate)?d.paidDate:F.todayISO();}else{b.paidAmountCents=null;b.paidDate=null;}
    b.demo=false;b.name=d.name.trim();b.amountCents=cents;b.dueDate=d.dueDate;b.category=d.category;b.status=d.status;b.notes=(d.notes||'').trim();b.essential=d.essential==='on';persist();closeDialog();render();showToast('Ocorrência atualizada.');
  }
  function submitBudget(form) {const d=getFormData(form);const cents=amount(d,'limit');const category=d.category;if(!category)throw new Error('Escolha uma categoria.');const oldCategory=form.dataset.category;let found=state.budgets.find(b=>b.category===category);if(oldCategory&&oldCategory!==category){state.budgets=state.budgets.filter(b=>b.category!==oldCategory);found=state.budgets.find(b=>b.category===category);}if(found){found.limitCents=cents;found.demo=false;}else state.budgets.push({category,limitCents:cents,demo:false});persist();closeDialog();render();showToast('Limite salvo.');}
  function submitGoal(form) {const d=getFormData(form);const target=amount(d,'target');const initial=amount(d,'initial');const monthly=String(d.monthly||'').trim()===''?0:amount(d,'monthly');if(target<=0)throw new Error('A meta deve ser maior que zero.');if(d.deadline&&!F.validDate(d.deadline))throw new Error('Data-alvo inválida.');if(!d.name.trim())throw new Error('Informe um nome.');const editId=form.dataset.id;const old=editId?state.goals.find(g=>g.id===editId):null;const g={...(old||{}),id:editId||id(),demo:false,name:d.name.trim(),targetCents:target,initialCents:initial,deadline:d.deadline||null,monthlyCents:monthly,priority:d.priority,status:d.status,kind:d.kind};if(old)state.goals=state.goals.map(x=>x.id===editId?g:x);else state.goals.push(g);persist();closeDialog();render();showToast(old?'Objetivo atualizado.':'Objetivo criado.');}
  function submitGoalOperation(form) {const d=getFormData(form),goal=state.goals.find(g=>g.id===form.dataset.goalId);if(!goal)throw new Error('Objetivo não encontrado.');const cents=amount(d);if(cents<=0)throw new Error('O valor deve ser maior que zero.');if(!F.validDate(d.date))throw new Error('Data inválida.');const withdrawal=d.operation==='withdrawal';if(withdrawal&&cents>F.getGoalBalance(state,goal))throw new Error('A retirada supera o saldo do objetivo.');state.transactions.push({id:id(),type:withdrawal?'goal_withdrawal':'goal_contribution',amountCents:cents,date:d.date,category:'Objetivos',description:(d.description||goal.name).trim(),account:'',status:'paid',goalId:goal.id,essential:false,demo:false});persist();closeDialog();render();showToast(withdrawal?'Retirada registrada.':'Aporte registrado.');}
  function submitEmergencyOperation(form) {const d=getFormData(form),cents=amount(d);if(cents<=0)throw new Error('O valor deve ser maior que zero.');if(!F.validDate(d.date))throw new Error('Data inválida.');const withdrawal=d.operation==='withdrawal';if(withdrawal&&cents>F.getEmergencyBalance(state))throw new Error('A retirada supera o saldo da reserva.');state.transactions.push({id:id(),type:withdrawal?'emergency_withdrawal':'emergency_contribution',amountCents:cents,date:d.date,category:'Reserva de emergência',description:(d.description||(withdrawal?'Retirada da reserva':'Aporte na reserva')).trim(),account:'',status:'paid',essential:false,demo:false});persist();closeDialog();render();showToast('Movimentação da reserva registrada.');}
  function submitSettings(form) {const d=getFormData(form);const sal=amount(d,'salaryExpected');const day=Number(d.salaryDay),months=Number(d.essentialMonths),alert70=Number(d.alert70),alert90=Number(d.alert90);if(!Number.isInteger(day)||day<1||day>31)throw new Error('Dia de recebimento deve estar entre 1 e 31.');if(!Number.isInteger(months)||months<0||months>60)throw new Error('Meses de reserva deve estar entre 0 e 60.');if(!Number.isInteger(alert70)||alert70<1||alert70>100||!Number.isInteger(alert90)||alert90<1||alert90>100)throw new Error('Os alertas devem estar entre 1% e 100%.');const cats=Array.from(new Set(d.categories.split(',').map(x=>x.trim()).filter(Boolean)));if(!cats.length)throw new Error('Mantenha ao menos uma categoria.');let bank=null;if(String(d.bankBalance||'').trim()!==''){bank=F.centsFromInput(d.bankBalance);if(!Number.isSafeInteger(bank)||bank<0)throw new Error('Saldo bancário inválido.');}let target=null;if(String(d.manualTarget||'').trim()!==''){target=F.centsFromInput(d.manualTarget);if(!Number.isSafeInteger(target)||target<0)throw new Error('Meta manual inválida.');}const emergencyInitial=amount(d,'emergencyInitial');state.demoSettingsEdited=state.demoSettingsEdited||{};if(sal!==state.settings.salaryExpectedCents)state.demoSettingsEdited.salaryExpectedCents=true;if(bank!==state.settings.currentBankBalanceCents)state.demoSettingsEdited.currentBankBalanceCents=true;if(emergencyInitial!==(state.emergencyInitialCents||0))state.demoSettingsEdited.emergencyInitialCents=true;state.settings={...state.settings,salaryExpectedCents:sal,salaryDay:day,currentBankBalanceCents:bank,essentialMonths:months,manualEmergencyTargetCents:target,alert70,alert90,categories:cats};state.emergencyInitialCents=emergencyInitial;persist();render();showToast('Configurações salvas.');}
  function toggleBillPaid(itemId) {const b=state.bills.find(x=>x.id===itemId);if(!b)return;if(b.status==='paid'){if(!confirm(`Desfazer a baixa da conta “${b.name}”? Ela voltará a ficar pendente.`))return;b.status='pending';b.paidAmountCents=null;b.paidDate=null;}else{if(!confirm(`Marcar “${b.name}” como paga por ${brl(b.amountCents)}?`))return;b.status='paid';b.paidAmountCents=b.amountCents;b.paidDate=F.todayISO();}b.demo=false;persist();render();showToast('Situação da conta atualizada.');}
  function deleteBill(itemId) {const b=state.bills.find(x=>x.id===itemId);if(!b)return;if(!confirm(`Excluir somente a ocorrência “${b.name}” de ${fmtDate(b.dueDate)}?`))return;if(b.occurrenceKey){state.cancelledOccurrences=Array.isArray(state.cancelledOccurrences)?state.cancelledOccurrences:[];if(!state.cancelledOccurrences.includes(b.occurrenceKey))state.cancelledOccurrences.push(b.occurrenceKey);}state.bills=state.bills.filter(x=>x.id!==itemId);persist();render();showToast('Ocorrência excluída.');}
  function toggleTemplate(itemId) {const t=state.billTemplates.find(x=>x.id===itemId);if(!t)return;t.active=t.active===false;t.demo=false;persist();render();showToast(t.active?'Modelo retomado.':'Modelo pausado.');}
  function deleteTemplate(itemId) {const t=state.billTemplates.find(x=>x.id===itemId);if(!t)return;if(!confirm(`Excluir o modelo “${t.name}”? As ocorrências já existentes serão mantidas.`))return;state.billTemplates=state.billTemplates.filter(x=>x.id!==itemId);persist();render();showToast('Modelo excluído; histórico mantido.');}
  function deleteTransaction(itemId) {const t=state.transactions.find(x=>x.id===itemId);if(!t)return;if(!confirm(`Excluir “${t.description||transactionTypeLabel(t.type)}” de ${brl(t.amountCents)}? Os totais serão recalculados.`))return;state.transactions=state.transactions.filter(x=>x.id!==itemId);persist();render();showToast('Movimentação excluída.');}
  function toggleGoal(itemId) {const g=state.goals.find(x=>x.id===itemId);if(!g)return;if(g.status==='active')g.status='paused';else if(g.status==='paused')g.status='active';else g.status='active';g.demo=false;persist();render();showToast('Situação do objetivo atualizada.');}
  function deleteGoal(itemId) {const g=state.goals.find(x=>x.id===itemId);if(!g)return;if(state.transactions.some(t=>t.goalId===itemId)){if(!confirm(`“${g.name}” tem movimentações vinculadas. Excluir objetivo e também as movimentações dele? Essa ação altera o histórico.`))return;state.transactions=state.transactions.filter(t=>t.goalId!==itemId);}else if(!confirm(`Excluir o objetivo “${g.name}”?`))return;state.goals=state.goals.filter(x=>x.id!==itemId);closeDialog();persist();render();showToast('Objetivo excluído.');}
  function clearDemo() {
    const hasDemo=state.demoMode||state.transactions.some(x=>x.demo)||state.bills.some(x=>x.demo)||state.billTemplates.some(x=>x.demo)||state.goals.some(x=>x.demo)||state.budgets.some(x=>x.demo);
    if(!hasDemo){showToast('Não há dados de demonstração para remover.');return;}
    if(!confirm('Remover itens de demonstração? Registros que você editou ou criou serão mantidos.'))return;
    const demoTemplateIds=state.billTemplates.filter(t=>t.demo).map(t=>t.id);
    state.transactions=state.transactions.filter(t=>!t.demo);
    state.bills=state.bills.filter(b=>!b.demo);
    state.billTemplates=state.billTemplates.filter(t=>!t.demo);
    state.goals=state.goals.filter(g=>!g.demo);
    state.budgets=state.budgets.filter(b=>!b.demo);
    state.cancelledOccurrences=(state.cancelledOccurrences||[]).filter(key=>!demoTemplateIds.some(templateId=>key.startsWith(`${templateId}:`)));
    state.demoSettingsEdited=state.demoSettingsEdited||{};
    if(!state.demoSettingsEdited.salaryExpectedCents)state.settings.salaryExpectedCents=0;
    if(!state.demoSettingsEdited.currentBankBalanceCents)state.settings.currentBankBalanceCents=null;
    if(!state.demoSettingsEdited.emergencyInitialCents)state.emergencyInitialCents=0;
    state.demoMode=false;persist();setView('dashboard');showToast('Dados de exemplo removidos. Confira suas configurações.');
  }
  function wipeAll() {const phrase=prompt('Para apagar tudo de forma definitiva neste navegador, digite APAGAR. Faça backup antes, pois não há desfazer.');if(phrase!=='APAGAR'){showToast('Ação cancelada.');return;}state=F.initialState();storageLoadError=false;persist();setView('dashboard');showToast('Todos os dados locais foram apagados.');}
  function downloadBlob(name, blob) {const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
  function exportJSON() {try{const payload={...state,backupCreatedAt:new Date().toISOString(),app:'Meu Financeiro'};downloadBlob(`meu-financeiro-backup-${F.todayISO()}.json`,new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}));showToast('Backup JSON preparado. Guarde-o em local privado.');}catch(e){showToast('Não foi possível gerar o backup.');}}
  function csvCell(v) {const s=String(v??'');return `"${s.replace(/"/g,'""')}"`;}
  function exportCSV() {const headers=['data','tipo','descricao','categoria','valor_centavos','valor_R$','situacao','conta_meio','observacao'];const rows=[headers];state.transactions.slice().sort((a,b)=>a.date.localeCompare(b.date)).forEach(t=>rows.push([t.date,transactionTypeLabel(t.type),t.description||'',t.category||'',t.amountCents,(t.amountCents/100).toFixed(2).replace('.',','),t.status,t.account||'',t.essential?'essencial':'']));state.bills.slice().sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).forEach(b=>rows.push([b.dueDate,'Conta',b.name,b.category,b.status==='paid'?F.actualBillAmount(b):b.amountCents,((b.status==='paid'?F.actualBillAmount(b):b.amountCents)/100).toFixed(2).replace('.',','),b.status==='paid'?'paga':'pendente','',b.notes||'']));const csv='\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n');downloadBlob(`meu-financeiro-movimentacoes-${F.todayISO()}.csv`,new Blob([csv],{type:'text/csv;charset=utf-8'}));showToast('CSV exportado.');}
  async function importJSON(file) {if(!file)return;try{const text=await file.text();const parsed=JSON.parse(text);F.validateState(parsed);if(!confirm('O backup parece válido. Substituir todos os dados atuais por este backup? Recomendamos exportar uma cópia antes.'))return;delete parsed.backupCreatedAt;delete parsed.app;state=parsed;storageLoadError=false;currentMonth=F.monthISO();persist();setView('dashboard');showToast('Backup restaurado com sucesso.');}catch(e){console.error(e);showToast(`Backup recusado: ${e.message||'arquivo inválido'}`);}finally{$('#backupPicker').value='';}}
  function submitFilter(form) {const d=getFormData(form);let tx=allTransactionsForMonth().slice().sort((a,b)=>b.date.localeCompare(a.date));const q=(d.q||'').trim().toLocaleLowerCase('pt-BR');if(q)tx=tx.filter(t=>(t.description||'').toLocaleLowerCase('pt-BR').includes(q)||(t.category||'').toLocaleLowerCase('pt-BR').includes(q));if(d.type)tx=tx.filter(t=>t.type===d.type);if(d.category)tx=tx.filter(t=>t.category===d.category);$('#transactionResults').innerHTML=transactionListMarkup(tx);}
  function submitBillFilter(value) {let bills=getBillList();if(value==='pending')bills=bills.filter(b=>b.status!=='paid');if(value==='paid')bills=bills.filter(b=>b.status==='paid');if(value==='late')bills=bills.filter(b=>b.status!=='paid'&&b.dueDate<F.todayISO());$('#billResults').innerHTML=billListMarkup(bills);}

  document.addEventListener('click',event=>{
    const nav=event.target.closest('[data-view]');if(nav){event.preventDefault();setView(nav.dataset.view);return;}
    const action=event.target.closest('[data-action]');if(action){openByAction(action.dataset.action,action);return;}
  });
  $('#prevMonth').addEventListener('click',()=>{const [y,m]=currentMonth.split('-').map(Number),d=new Date(y,m-2,1);currentMonth=F.monthISO(d);render();});
  $('#nextMonth').addEventListener('click',()=>{const [y,m]=currentMonth.split('-').map(Number),d=new Date(y,m,1);currentMonth=F.monthISO(d);render();});
  $('#monthPicker').addEventListener('change',e=>{if(/^\d{4}-\d{2}$/.test(e.target.value)){currentMonth=e.target.value;render();}});
  $('#quickAdd').addEventListener('click',()=>openByAction('add-transaction'));
  $('#floatingAdd').addEventListener('click',()=>openByAction('add-transaction'));
  $('#openSettings').addEventListener('click',()=>setView('settings'));
  $('#closeDialog').addEventListener('click',closeDialog);
  dialog.addEventListener('click',e=>{if(e.target===dialog)closeDialog();});
  dialogBody.addEventListener('click',event=>{const action=event.target.closest('[data-action]');if(action)openByAction(action.dataset.action,action);});
  dialogBody.addEventListener('change',event=>{
    if(event.target.id==='txType'){
      const type=event.target.value,oldCat=$('#txCategory')?.value,oldAmount=F.centsFromInput($('#txAmount')?.value||'0'),oldDate=$('#txDate')?.value,oldDescription=$('#txDescription')?.value,oldAccount=$('#txAccount')?.value,oldGoal=$('#txGoal')?.value,oldEssential=$('[name=essential]')?.checked;
      const allowed = type==='income' ? ['Salário','Renda extra',...(state.settings.categories||[]).filter(c=>/sal[aá]rio|renda/i.test(c))] : type==='expense' ? (state.settings.categories||[]).filter(c=>!['Salário','Renda extra'].includes(c)) : ['Objetivos','Reserva de emergência','Outros'];
      const fake={type,amountCents:Number.isSafeInteger(oldAmount)&&oldAmount>0?oldAmount:0,date:F.validDate(oldDate)?oldDate:F.todayISO(),category:allowed.includes(oldCat)?oldCat:allowed[0],description:oldDescription||'',account:oldAccount||'',status:type==='income'?'received':type==='expense'?'paid':'paid',essential:!!oldEssential,goalId:oldGoal};
      const holder=dialogBody;holder.innerHTML=transactionForm(fake);const amt=$('#txAmount');if(amt)amt.focus();
    }
    if(event.target.id==='billFilter')submitBillFilter(event.target.value);
  });
  dialogBody.addEventListener('submit',event=>{
    event.preventDefault();const form=event.target;
    try{switch(form.id){case'transactionForm':submitTransaction(form);break;case'billForm':submitBillTemplate(form);break;case'billOccurrenceForm':submitBillOccurrence(form);break;case'budgetForm':submitBudget(form);break;case'goalForm':submitGoal(form);break;case'goalOperationForm':submitGoalOperation(form);break;case'emergencyOperationForm':submitEmergencyOperation(form);break;}}catch(e){showToast(e.message||'Confira os dados preenchidos.');}
  });
  content.addEventListener('submit',event=>{event.preventDefault();const form=event.target;try{if(form.id==='settingsForm')submitSettings(form);else if(form.id==='transactionFilter')submitFilter(form);}catch(e){showToast(e.message||'Confira os dados preenchidos.');}});
  content.addEventListener('change',event=>{if(event.target.id==='billFilter')submitBillFilter(event.target.value);});
  content.addEventListener('click',event=>{const a=event.target.closest('[data-action]');if(a&&a.dataset.action==='clear-tx-filter'){const form=$('#transactionFilter');form.reset();submitFilter(form);}});
  $('#backupPicker').addEventListener('change',e=>importJSON(e.target.files&&e.target.files[0]));

  state=loadState();prepareMonth(currentMonth);persist(false);render();
  if(!storageAvailable) showToast('O armazenamento local não está acessível. Verifique o navegador e faça backup.');
})();
